var DATA = {"mode": "task", "name": "Forge street batch 1", "frames": 15000, "jobs": 8};
function show(k,v){console.log(k+": "+v);}
var m=DATA.mode;
if(m==="task"){
  show("Task",DATA.name);
  show("Frames",DATA.frames);
  show("Jobs",DATA.jobs+" (split for annotators)");
}else if(m==="shape"){
  show("Shape",DATA.shape);
  show("Use",DATA.use);
}else if(m==="interpolate"){
  show("Keyframes",DATA.kf+" at frames "+DATA.at.join(", "));
  show("In-between","interpolated automatically");
  show("Saved",DATA.saved+" manual boxes");
}else if(m==="format"){
  show("Convert","CVAT XML -> "+DATA.to);
  show("Use","feed the training framework directly");
}else if(m==="sdk"){
  show("SDK","cvat-sdk (Python)");
  show("Does","tasks, jobs, annotations as code");
  show("Example",DATA.ex);
}else if(m==="install"){
  show("Deploy","docker compose up -d");
  show("Then","open the web UI, create an organization");
}else if(m==="auto"){
  show("Auto-annotation","models like SAM propose masks");
  show("Humans","verify and correct");
}else if(m==="track"){
  show("Tracking","one label follows the object across frames");
  show("Frames labeled",DATA.n);
}else if(m==="attr"){
  show("Attributes",DATA.attrs.join(", "));
  show("Use","occluded, truncated, parked...");
}else if(m==="review"){
  show("Review job","separate job type for verification");
  show("Issues","raised per shape");
}else if(m==="cloud"){
  show("Cloud storage","S3, GCS, Azure mounted as data");
}else if(m==="job"){
  show("Job",DATA.n+" of "+DATA.of);
  show("Assignee",DATA.who);
  show("State",DATA.state);
}else if(m==="stats"){
  show("Annotated frames",DATA.done+" / "+DATA.total);
  show("Progress",Math.round(DATA.done/DATA.total*100)+"%");
}else if(m==="quality"){
  show("Agreement",DATA.agree+"%");
  show("Gold frames","known-answer checks");
}else if(m==="workflow"){
  console.log("Annotation workflow:");DATA.steps.forEach(function(s,i){console.log("  "+(i+1)+". "+s);});
}
